consultasKQLyVerificacion.consulta:
Connect-ExchangeOnline -ShowBanner:$false
Search-UnifiedAuditLog -StartDate (Get-Date).AddDays(-7) -EndDate (Get-Date) -RecordType CopilotInteraction -ResultSize 1000 |
ForEach-Object {
  $d = $_.AuditData | ConvertFrom-Json
  if ($d.AppIdentity -like '*SecurityCopilot*' -or $d.AppHost -like 'Copilot in *') {
    [PSCustomObject]@{ Date = $_.CreationDate; User = $_.UserIds; Op = $_.Operations; AppIdentity = $d.AppIdentity; Host = $d.AppHost; Agent = $d.AgentName }
  }
} | Format-Table -AutoSize

Connect-MgGraph -Scopes 'Organization.Read.All'
$skus = Get-MgSubscribedSku | Where-Object { $_.SkuPartNumber -match 'SPE_E5|M365_E5|SPE_E7|M365_E7' -and $_.CapabilityStatus -eq 'Enabled' }
$seats = ($skus.PrepaidUnits.Enabled | Measure-Object -Sum).Sum
$scus = [Math]::Min(10000, [Math]::Round(($seats / 1000.0) * 400, 1))
[PSCustomObject]@{ PaidE5E7Seats = $seats; MonthlyIncludedSCUs = $scus; MaxCapReached = ($scus -eq 10000) }
